/**
 * Registrations of the Android device panel: its copy, the right sidebar tab type with its guide entry, and the
 * tab's body and title, which call the device panel Remote.
 * Generated by ttoken/apply-brand.mjs from ttoken/device/src/client/mount.ts; edit it there.
 */

import type { Context } from '@deepseek-ai/cordis'
import type {} from '@deepseek-ai/dsh-api-remotes/client'
import type {} from '@deepseek-ai/dsh-api-session-controller/client'
import type {} from '@deepseek-ai/dsh-client-locale/client'
import type {} from '@deepseek-ai/dsh-client-ui-conversation/client'
import type {} from '@deepseek-ai/dsh-client-ui-renderer/client'
import type {} from '@deepseek-ai/dsh-client-ui-sidebar-right/client'
import type {} from '@deepseek-ai/dsh-experimental-android-device/remote'
import type { SessionId } from '@deepseek-ai/dsh-session/types'
import type { TypertRemoteContribution } from '@deepseek-ai/dsh-typert-protocol'
import { DeviceArtwork, DevicePanel, DeviceTitle, type DevicePanelInjected } from './DevicePanel.tsx'
import { de, en, es, fr, ja, NS, pt, ru, zh } from './locales.ts'

/** Services required before the Remote contribution mounts. */
export const inject = ['remote', 'slots', 'locale', 'sidebarRightTabs', 'sessions']

/** Tab implementation identity, the key of its body and title. */
const TAB_ID = '@deepseek-ai/dsh-experimental-android-device'

/** Android platform-tools download page, shown when adb is missing. */
const PLATFORM_TOOLS_URL = 'https://developer.android.com/tools/releases/platform-tools'

/**
 * Open a URL in a new browsing context without giving it access to this page.
 * @param url - web URL.
 */
function openLink(url: string): void {
  window.open(url, '_blank', 'noopener,noreferrer')
}

function registerUi(ctx: Context): void {
  ctx.effect(() => ctx.locale.register(NS, { zh, en, ja, es, fr, de, ru, pt }), 'device-panel: dictionaries')
  const t = ctx.locale.bind(NS)
  ctx.effect(() => ctx.sidebarRightTabs.register({
    id: TAB_ID,
    kind: 'android-device',
    priority: 'builtin',
    title: () => t('title'),
    guide: [{ id: 'device', order: 40, title: () => t('guide.title'), description: () => t('guide.description'), icon: DeviceArtwork }],
  }), 'device-panel: tab type')
  const remote = ctx.remote.devicePanel
  /** Append a note to the Session's draft and focus it; false when the Session has no composer. */
  const addToDraft = (sessionId: SessionId, note: string): boolean => {
    const scope = ctx.sessions.scope(sessionId)
    const conversation = scope?.get('conversation')
    if (scope === undefined || conversation === undefined) return false
    const input = conversation.input.for(scope)
    const draft = input.state.getSnapshot().draft.trimEnd()
    input.setDraft(draft === '' ? note : `${draft}\n\n${note}`)
    input.focus()
    return true
  }
  ctx.slots.inject('sidebar.right.pane.tab', () => ctx.slots.register({
    name: 'sidebar.right.pane.tab',
    key: TAB_ID,
    locale: NS,
    inject: (sessionId: SessionId): DevicePanelInjected => ({
      listDevices: signal => remote.devices(signal),
      readScreen: (serial, signal) => remote.screen(serial, signal),
      send: (serial, input) => remote.input(serial, input),
      openMirror: serial => remote.mirror(serial),
      addToDraft: note => addToDraft(sessionId, note),
      openPlatformTools: () => { openLink(PLATFORM_TOOLS_URL) },
    }),
  }, DevicePanel))
  ctx.slots.inject('sidebar.right.pane.tab.title', () => ctx.slots.register({
    name: 'sidebar.right.pane.tab.title', key: TAB_ID, locale: NS,
  }, DeviceTitle))
}

/**
 * Mount the device panel Remote, then the UI that calls it; the UI is withdrawn before the Remote.
 * @param ctx - client plugin lifetime.
 * @param contribution - generated device panel Remote definitions.
 * @returns the disposer that removes both contributions.
 */
export async function mountDevicePanel(ctx: Context, contribution: TypertRemoteContribution): Promise<() => Promise<void>> {
  const unmountRemote = await ctx.remote.$mount(contribution)
  const ui = ctx.inject(['remote.devicePanel', ...inject.slice(1)], registerUi)
  try {
    await ui
  } catch (error) {
    await ui.dispose()
    await unmountRemote()
    throw error
  }
  return async () => {
    await ui.dispose()
    await unmountRemote()
  }
}
